report={'schemaVersion':1,'documentType':'independent-machine-V-A-seven-raster-decisions','createdAtUTC':datetime.datetime.now(datetime.timezone.utc).isoformat(),'reviewerRole':'independent machine V-A; not image author','status':'PARTIAL_KEEP_WITH_FOUR_CONCRETE_REVISE_REQUESTS','summary':{'KEEP':sum(x['decision']=='KEEP' for x in out),'REVISE':sum(x['decision']=='REVISE' for x in out),'scientificallyMisleadingSelectedDrawings':1,'selectedNativeScienceCorrectButMobileInformationTooSmall':3,'actualOriginalRastersViewed':7,'actualSelectedPNGRastersViewed':7,'actualSelectedBrowserScreenshotsViewed':14},'scope':'Candidate V review with exact current DE/EN whole goals and actual assets. Isolated Chromium harness only, not complete app/native book pages/host acceptance. No P/source review, HumanApproval, integration or new strict closure.','rows':out,'activeWrites':0,'imageGeneration':False,'peerBRead':False}
